def user_dir() -> Path:
    """Return the directory used to store mlc-related state.

    Previously this came from llm.user_dir(); here we default to ~/.llm.
    """
    return Path(os.environ.get("LLM_USER_DIR", Path.home() / ".llm")).expanduser()


def _ensure_models_dir():
    directory = user_dir() / "llama-cpp" / "models"
    directory.mkdir(parents=True, exist_ok=True)
    return directory


def _ensure_models_file():
    directory = user_dir() / "llama-cpp"
    directory.mkdir(parents=True, exist_ok=True)
    filepath = directory / "models.json"
    if not filepath.exists():
        filepath.write_text("{}")
    return filepath


def register_models(register):
    """Register available MLC models.

    This was previously a llm.hookimpl; callers should pass in the
    appropriate register callback.
    """
    directory = user_dir() / "mlc"
    models_dir = directory / "dist" / "prebuilt"
    if not models_dir.exists():
        return
    for child in models_dir.iterdir():
        if child.is_dir() and child.name != "lib":
            # It's a model! Register it
            register(
                MlcModel(
                    model_id=child.name,
                    model_path=str(child.absolute()),
                )
            )


