class MlcResponseParams(BaseModel):
    temperature: Optional[float] = Field(description="Temperature for the model")
    top_p: Optional[float] = Field(description="Top-p sampling parameter")
    repeat_penalty: Optional[float] = Field(
        description="Repeat penalty parameter for the model"
    )
    max_tokens: Optional[int] = Field(description="Maximum tokens to generate")


class MlcModel(BaseModel):
    model_id: str
    model_path: str

    def register_model(self, models):
        models[self.model_id] = self

    def __call__(self, prompt: str, params: Optional[MlcResponseParams] = None) -> str:
        with contextlib.ExitStack() as stack:
            env = os.environ.copy()
            if params:
                env["MLC_TEMPERATURE"] = str(params.temperature)
                env["MLC_TOP_P"] = str(params.top_p)
                env["MLC_REPEAT_PENALTY"] = str(params.repeat_penalty)
                env["MLC_MAX_TOKENS"] = str(params.max_tokens)
            process = subprocess.Popen(
                ["mlc_chat_cli", "--model", self.model_path],
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                env=env,
            )
            stdout, stderr = process.communicate(input=prompt)
            if process.returncode != 0:
                raise RuntimeError(f"mlc_chat failed: {stderr}")
            return stdout.strip()
"}

